"""Build the small, self-contained Noor Hidayah public site. Python standard library only."""
from pathlib import Path
from html import escape
import json

SITE = Path(__file__).resolve().parents[1]
BASE = 'https://apps.mohdshayan.com/noor-hidayah/'
PRIVACY = 'https://apps.mohdshayan.com/privacy-policies/noor-hidayah-privacy-policy.html'
SUPPORT = 'https://apps.mohdshayan.com/privacy-policies/noor-hidayah-support.html'
DELETION = 'https://apps.mohdshayan.com/privacy-policies/noor-hidayah-delete-account.html'
EMAIL = 'contactus@noorhidayahofficial.com'
NAV = [('index.html', 'Home'), ('for-pilgrims.html', 'For Pilgrims'), ('for-operators.html', 'For Operators'), ('about.html', 'About'), ('contact.html', 'Contact')]

def nav(current):
    return ''.join(f'<a href="{href}"'+(' aria-current="page"' if href == current else '')+f'>{label}</a>' for href,label in NAV)

def shot(name, alt, hero=False):
    return f'<img src="assets/{name}-360.webp" srcset="assets/{name}-360.webp 360w, assets/{name}-720.webp 720w" sizes="(max-width: 767px) 234px, 265px" width="360" height="800" alt="{escape(alt)}" '+('fetchpriority="high"' if hero else 'loading="lazy"')+' decoding="async">'

def page(file,title,description,body,robots=None):
    url=BASE if file=='index.html' else BASE+file
    html=f'''<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(title)}</title><meta name="description" content="{escape(description)}">
{f'<meta name="robots" content="{robots}">' if robots else ""}
<link rel="canonical" href="{url}"><link rel="icon" href="assets/favicon.ico"><link rel="apple-touch-icon" href="assets/icon.png">
<meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/icon.png"><meta name="twitter:card" content="summary">
<link rel="preload" href="assets/fonts/mukta-400.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="assets/site.css">
</head><body>
<a class="skip" href="#main">Skip to content</a>
<header><div class="wrap header"><a class="brand" href="index.html"><img src="assets/icon.png" alt="" width="40" height="40">Noor Hidayah</a><nav class="desktop-nav" aria-label="Main navigation">{nav(file)}</nav><details class="mobile-nav"><summary>Menu</summary><nav aria-label="Mobile navigation"><div>{nav(file)}</div></nav></details></div></header>
{body}
<footer><div class="wrap"><div class="footer-top"><a class="brand" href="index.html"><img src="assets/icon.png" alt="" width="40" height="40" loading="lazy">Noor Hidayah</a><nav class="footer-links" aria-label="Information"><a href="{SUPPORT}">Support</a><a href="{PRIVACY}">Privacy</a><a href="terms.html">Terms (draft)</a><a href="{DELETION}">Delete account or data</a><a href="about.html#company">Company</a><a href="https://noorhidayah.com/en/operators">Operator directory</a></nav></div><div class="footer-bottom"><p>© 2026 SOSA Consulting Services Private Limited</p><p>Website: English. <a href="for-pilgrims.html#languages">App languages</a></p><a href="mailto:{EMAIL}">{EMAIL}</a></div></div></footer>
</body></html>'''
    assert '—' not in html and '–' not in html, file
    (SITE/file).write_text(html.replace("><", ">\n<")+"\n")

home=f'''<main id="main">
<section class="wrap hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow">Your digital pilgrimage companion</p><h1 id="hero-title">Your Hajj &amp; Umrah journey, made simpler.</h1><p class="lead">Pilgrimage guidance, offline maps, prayer tools and your operator-shared itinerary, together in one digital companion.</p><div class="actions"><a class="button" href="contact.html#launch">Join the launch list</a><a class="button secondary" href="for-operators.html">For Operators</a></div></div><div class="hero-device">{shot('home','Current Noor Hidayah Home screen with prayer countdown, services and assistance controls.',True)}</div></section>
<section class="wrap" id="features" aria-labelledby="features-title"><div class="intro"><h2 id="features-title">Everything important, in one place.</h2></div><div class="benefits">
<article class="benefit"><span class="benefit-marker" aria-hidden="true"></span><div><h3>Pilgrimage guidance</h3><p>Follow reviewed Hajj and Umrah steps, read duas and keep your own progress on your phone.</p></div></article>
<article class="benefit"><span class="benefit-marker" aria-hidden="true"></span><div><h3>Offline maps</h3><p>Use the bundled Makkah and Madinah maps without a live connection. Download map updates when you are online.</p></div></article>
<article class="benefit"><span class="benefit-marker" aria-hidden="true"></span><div><h3>Prayer tools</h3><p>See prayer times, find the Qibla direction and use the tasbih counter throughout your journey.</p></div></article>
<article class="benefit"><span class="benefit-marker" aria-hidden="true"></span><div><h3>Your group, together</h3><p>View your operator’s itinerary and announcements after they reach your phone. New group information needs connectivity.</p></div></article>
</div><a class="section-link" href="for-pilgrims.html">Explore the pilgrim app</a></section>
<section class="showcase" id="app" aria-labelledby="app-title"><div class="wrap"><div class="intro"><h2 id="app-title">Designed for the journey.</h2><p>Real screens from the current test build, with example journey data.</p></div><div class="gallery">
<figure>{shot('umrah','Umrah tab showing journey progress and the next reviewed ritual step.')}<figcaption><strong>Your Umrah, step by step</strong>Keep the next step and your progress close.</figcaption></figure>
<figure>{shot('hajj','Hajj tab showing the selected journey and its reviewed phases.')}<figcaption><strong>Guidance for Hajj</strong>Follow the flow for your selected Hajj journey.</figcaption></figure>
<figure>{shot('services','Home services for Qibla, tasbih and prayer times, with Community marked coming soon.')}<figcaption><strong>Useful everyday tools</strong>Qibla, tasbih and prayer times in one place.</figcaption></figure>
</div><p class="note">App launch coming soon. Community is marked coming soon in the app and is not available yet.</p><a class="section-link" href="contact.html#launch">Join the launch list</a></div></section>
<section class="wrap" id="operators" aria-labelledby="operators-title"><div class="operator-panel"><div class="intro"><h2 id="operators-title">Deliver a more connected pilgrim experience.</h2><p>Share itineraries, announcements and assistance information through a platform designed for Hajj and Umrah operators.</p><div class="actions"><a class="button" href="for-operators.html">Partner with us</a></div></div><ul class="plain-list"><li><strong>Organise the journey</strong><span>Manage groups and publish travel details from the operator dashboard.</span></li><li><strong>Keep people informed</strong><span>Send announcements and give pilgrims one place to find their itinerary.</span></li><li><strong>Support your pilgrims</strong><span>Staff can see trip assistance alerts while their dashboard or Partner app is open.</span></li></ul></div></section>
<section class="wrap trust" aria-labelledby="trust-title"><div class="intro"><h2 id="trust-title">Built around the needs of pilgrims.</h2></div><div class="trust-grid"><article><h3>Guidance without a connection</h3><p>The bundled ritual guide, duas and map packs work offline. Sign-in, new group updates and sending assistance requests need a connection.</p></article><article><h3>Four app languages</h3><p>English, Hindi, Urdu and Kashmiri are available. Translations remain marked as first drafts where review is pending. This website is in English.</p></article><article><h3>Clear data responsibilities</h3><p>Your operator manages the records it enters. Access depends on the person’s role. The privacy notice explains the information stored, retention and your choices.</p><a href="{PRIVACY}">Read the privacy notice</a></article><article><h3>Assistance, with clear limits</h3><p>During a trip, SOS sends an alert to your operator’s staff. It does not call emergency services or guarantee a response. For urgent help, contact local emergency services directly.</p><a href="{SUPPORT}">Support and assistance</a></article></div></section>
<section class="mission" id="about" aria-labelledby="about-title"><div class="wrap"><h2 id="about-title">Technology with a purpose.</h2><p>Our mission is to make the pilgrimage experience more informed, organised and connected, so pilgrims can focus on their worship.</p><a class="section-link" href="about.html">About Noor Hidayah</a></div></section>
<section class="wrap final" id="contact" aria-labelledby="final-title"><div><h2 id="final-title">Be part of the Noor Hidayah journey.</h2><p>Follow our launch as a pilgrim, or explore an operator partnership.</p></div><div class="actions"><a class="button" href="contact.html#launch">Join the launch list</a><a class="button secondary" href="for-operators.html">Partner with us</a></div></section>
</main>'''
page('index.html','Noor Hidayah | Your Hajj and Umrah companion','Pilgrimage guidance, offline maps, prayer tools and operator-shared itineraries. Explore Noor Hidayah and follow the upcoming app launch.',home)

pilgrims=f'''<main id="main" class="wrap page"><div class="page-head"><p class="eyebrow">For pilgrims</p><h1>Guidance to take with you.</h1><p class="lead">Prepare for your journey and keep useful guidance close, including when your connection is limited.</p><div class="actions"><a class="button" href="contact.html#launch">Join the launch list</a></div></div><div class="article"><section><h2>Prepare and follow your progress</h2><p>The app includes reviewed Umrah and Hajj guidance, duas, essentials and a personal progress checklist. Choose the Hajj journey that matches your arrangements. Ask a qualified scholar about your own circumstances; the app does not issue religious rulings.</p></section><section><h2>Find your way and your prayer time</h2><p>Makkah and Madinah map packs are bundled for offline use. Prayer times, Qibla direction and a tasbih counter are available on the phone. Check important times and places with your group leader.</p></section><section><h2>Travel with your operator</h2><p>Invited pilgrims can access operator-published itineraries and announcements when connected group services are available. Once received, journey information stays on the phone for offline reading. Signing in, receiving changes and sending messages or alerts need connectivity.</p><p>The service is in testing. Production group sync is being prepared, so this website does not promise live group updates to the public yet.</p></section><section id="languages"><h2>Read in your language</h2><p>The app supports English, Hindi, Urdu and Kashmiri. Urdu and Kashmiri use a right-to-left layout. Translations awaiting review are marked as first drafts. Arabic appears in relevant religious content; it is not an app interface language. This website is currently in English.</p></section><section><h2>Know where help goes</h2><p>On an active trip, SOS alerts your operator’s staff. Staff see alerts only while their dashboard or Noor Hidayah Partner app is open. SOS does not call an ambulance or police, may not reach anyone without a network, and is not an emergency service.</p><p>For trip arrangements, contact your operator first. For app support, <a href="{SUPPORT}">contact the support desk</a>.</p></section><section><h2>Availability</h2><p>The apps are in testing and are not yet listed publicly in the app stores. No store download is offered here. Community is marked coming soon and is not available yet.</p><a class="section-link" href="contact.html#launch">Join the launch list</a></section></div></main>'''
page('for-pilgrims.html','For pilgrims | Noor Hidayah','Explore the current pilgrim app: reviewed journey guidance, offline maps, prayer tools, languages and clear assistance limits.',pilgrims)

operators=f'''<main id="main" class="wrap page"><div class="page-head"><p class="eyebrow">For Hajj and Umrah operators</p><h1>Help your pilgrims stay informed.</h1><p class="lead">Bring group details, travel plans and announcements into one operator workspace. Give pilgrims a clearer place to find their journey information.</p><div class="actions"><a class="button" href="contact.html#operators">Discuss a partnership</a></div></div><div class="article"><section><h2>Built tools, in a testing service</h2><p>The operator dashboard supports pilgrim and group records, enquiries, itinerary publication and announcements. Noor Hidayah Partner gives invited staff access based on their role. The pilgrim app reads information received on the phone offline.</p><p>Public app-store launch and production group sync are still being prepared. We agree pilot scope before onboarding; we do not promise features or delivery dates that have not been confirmed.</p></section><section><h2>Plan the journey in one place</h2><ul><li>Manage groups and the pilgrim records your organisation is authorised to enter.</li><li>Publish authored travel details with the reviewed ritual guidance shown in the pilgrim app.</li><li>Send group announcements and let authorised staff view assistance alerts while their dashboard or Partner app is open.</li></ul></section><section><h2>Start with a conversation</h2><p>Email your organisation name, role and a short outline of what you need. We can discuss your operating model, confirm the available scope and agree the next onboarding or pilot step.</p><p>Do not send pilgrim lists, passports, visas or other personal documents in a marketing enquiry.</p><a class="button" href="contact.html#operators">Discuss a partnership</a></section><section><h2>Data and responsibilities</h2><p>Operators are responsible for the records they enter and the authority to enter them. Staff access follows assigned roles. Account consent is recorded when a pilgrim activates. See the <a href="{PRIVACY}">privacy notice</a> for current service facts, data retention and account rights.</p></section><section><h2>Common questions</h2><h3>Which languages are supported?</h3><p>The apps offer English, Hindi, Urdu and Kashmiri. Translations awaiting review are marked as first drafts.</p><h3>Is there a public price or booking promise?</h3><p>Partnership scope and commercial arrangements are discussed directly. This page does not quote a price, confirm a booking or offer travel services.</p><h3>Where can pilgrims find an operator?</h3><p>The <a href="https://noorhidayah.com/en/operators">operator directory</a> is separate from this partnership page. A listing is not a promise of availability or a recommendation of a trip.</p></section></div></main>'''
page('for-operators.html','For operators | Noor Hidayah','Explore operator tools for groups, itineraries and announcements, and contact Noor Hidayah to discuss a partnership or pilot.',operators)

